<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { allResources, http, showError } from '../api.js'
import { dateTime, shanghaiDate, slotTime, statusName } from '../format.js'
import { useDayCalendar } from '../composables/useDayCalendar.js'
const items = ref([]), busy = ref(false), saving = ref(false), editing = ref(false), deviceDialog = ref(false), dayDialog = ref(false), code = ref(null)
const form = reactive({}), dayDate = ref(shanghaiDate()), selected = ref(null)
const calendar = useDayCalendar((id, date) => http.get(`/resources/${id}/schedule`, { params: { date } }), (id, date, body) => http.put(`/admin/resources/${id}/days/${date}`, body))
const day = calendar.data, dayLoading = calendar.busy
async function load() { busy.value = true; try { items.value = await allResources() } catch (error) { showError(error) } finally { busy.value = false } }
function edit(row = null) { editing.value = !!row; Object.keys(form).forEach(k => delete form[k]); Object.assign(form, row ? { name: row.name, location: row.location, defaultOpenStartSlot: row.defaultOpenStartSlot, defaultOpenEndSlot: row.defaultOpenEndSlot, version: row.version, reason: '' } : { name: '', location: '', defaultOpenStartSlot: 16, defaultOpenEndSlot: 44, reason: '' }); selected.value = row?.id; deviceDialog.value = true }
async function save() {
  if (!form.name.trim() || !form.location.trim() || !form.reason.trim()) { ElMessage.warning('请填写设备名称、位置和操作原因'); return }
  if (form.defaultOpenStartSlot >= form.defaultOpenEndSlot) { ElMessage.warning('开放结束时间须晚于开始时间'); return }
  saving.value = true
  try { if (editing.value) await http.patch(`/admin/resources/${selected.value}`, form); else await http.post('/admin/resources', form); ElMessage.success('设备已保存'); deviceDialog.value = false; await load() } catch (error) { showError(error) } finally { saving.value = false }
}
async function readDay() { try { if (await calendar.load(selected.value, dayDate.value)) dayDialog.value = true } catch (error) { showError(error) } }
async function openDay(row) { selected.value = row.id; dayDate.value = shanghaiDate(); await readDay() }
async function saveDay() { if (!day.reason?.trim()) { ElMessage.warning('请填写操作原因'); return }; saving.value = true; try { await calendar.save(selected.value, dayDate.value); ElMessage.success('当日日历已保存'); dayDialog.value = false } catch (error) { showError(error) } finally { saving.value = false } }
async function issueCode(row) { try { code.value = await http.get(`/admin/resources/${row.id}/check-in-code`) } catch (error) { showError(error) } }
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>设备与日历</h1><p>维护设备基本信息，配置每天的开放时间。</p></div><div><el-button @click="load()" :loading="busy">刷新</el-button><el-button type="primary" @click="edit()">新增设备</el-button></div></div><section class="panel" v-loading="busy"><el-table :data="items" empty-text="暂无设备，点击新增设备开始配置"><el-table-column prop="id" label="ID" width="70" /><el-table-column prop="name" label="设备名称" min-width="170" /><el-table-column prop="location" label="位置" min-width="130" /><el-table-column label="默认开放" min-width="140"><template #default="{ row }">{{ slotTime(row.defaultOpenStartSlot) }} — {{ slotTime(row.defaultOpenEndSlot) }}</template></el-table-column><el-table-column label="状态" width="110"><template #default="{ row }">{{ statusName[row.status] }}</template></el-table-column><el-table-column label="管理" min-width="250"><template #default="{ row }"><el-button link type="primary" @click="edit(row)">编辑</el-button><el-button link type="primary" :disabled="saving || dayLoading" @click="openDay(row)">当日日历</el-button><el-button link type="primary" @click="issueCode(row)">签到码</el-button></template></el-table-column></el-table></section>
<el-dialog v-model="deviceDialog" :title="editing ? '编辑设备' : '新增设备'" width="min(560px, 94vw)"><el-form label-position="top" @submit.prevent="save"><el-form-item label="设备名称"><el-input v-model="form.name" maxlength="128" /></el-form-item><el-form-item label="设备位置"><el-input v-model="form.location" maxlength="128" /></el-form-item><div class="form-row"><el-form-item label="开放开始"><el-select v-model="form.defaultOpenStartSlot"><el-option v-for="n in 48" :key="n" :label="slotTime(n - 1)" :value="n - 1" /></el-select></el-form-item><el-form-item label="开放结束"><el-select v-model="form.defaultOpenEndSlot"><el-option v-for="n in 48" :key="n" :label="slotTime(n)" :value="n" /></el-select></el-form-item></div><el-form-item label="操作原因"><el-input v-model="form.reason" type="textarea" maxlength="255" /></el-form-item><el-button type="primary" native-type="submit" :loading="saving">保存设备</el-button></el-form></el-dialog>
<el-dialog v-model="dayDialog" title="配置当日日历" width="min(560px, 94vw)"><el-form label-position="top" v-loading="dayLoading" @submit.prevent="saveDay"><el-form-item label="日期"><el-date-picker v-model="dayDate" type="date" value-format="YYYY-MM-DD" :clearable="false" :disabled="saving" @change="readDay" /></el-form-item><el-form-item label="开放预约"><el-switch v-model="day.enabled" /></el-form-item><div class="form-row"><el-form-item label="开始时间"><el-select v-model="day.openStartSlot"><el-option v-for="n in 48" :key="n" :label="slotTime(n - 1)" :value="n - 1" /></el-select></el-form-item><el-form-item label="结束时间"><el-select v-model="day.openEndSlot"><el-option v-for="n in 48" :key="n" :label="slotTime(n)" :value="n" /></el-select></el-form-item></div><el-form-item label="操作原因"><el-input v-model="day.reason" type="textarea" maxlength="255" /></el-form-item><el-button type="primary" native-type="submit" :loading="saving" :disabled="dayLoading || !calendar.target.value">保存当日日历</el-button></el-form></el-dialog>
<el-dialog :model-value="!!code" title="现场签到码" width="min(620px, 94vw)" @close="code = null"><template v-if="code"><el-alert type="info" :closable="false" title="仅供设备现场展示，请勿公开分享。到期后需重新获取。" /><p>有效期至 {{ dateTime(code.expiresAt) }}</p><el-input :model-value="code.checkInCode" type="textarea" :rows="5" readonly aria-label="签到码" /><el-button class="spaced-top" @click="issueCode({ id: code.resourceId })">刷新签到码</el-button></template></el-dialog></template>
